<script lang="ts">
  import { page } from '$app/state';
  import { untrack } from 'svelte';
  import { useDemo } from '#lib/demo.svelte';
  import { phaseNames, productById, variantById } from '#lib/data';
  import { defaultKit, kitPrice, money } from '#lib/pricing';
  import type { KitSelection, Project } from '#lib/types';
  let { project }: { project: Project } = $props();
  const demo = useDemo();
  let complete = $state(false);
  let selections = $state<KitSelection[]>([]);
  let editing = $state('');
  $effect(() => { if (!demo.ready) return; const id = page.url.searchParams.get('edit') ?? ''; const desiredFinish = page.url.searchParams.get('finish'); const currentProject = project; untrack(() => { const cartLine = demo.state.cart.find((l) => l.id === id && l.projectId === currentProject.id); editing = cartLine ? id : ''; selections = cartLine?.selections ? JSON.parse(JSON.stringify(cartLine.selections)) : defaultKit(currentProject); if (!cartLine && desiredFinish) selections = selections.map((s) => { const v = productById(s.productId).variants.find((v) => v.finish === desiredFinish); return v ? { ...s, variantId: v.id } : s; }); complete = selections.some((s) => s.productId === 'herramientas'); }); });
  const total = $derived(kitPrice(selections));
  const valid = $derived(selections.some((s) => s.selected) && selections.every((s) => !s.selected || variantById(s.productId,s.variantId).stock > 0));
  function mode(value: boolean) { complete = value; selections = value ? [...selections, ...(selections.some((s) => s.productId === 'herramientas') ? [] : defaultKit(project,true).filter((s) => s.productId === 'herramientas'))] : selections.filter((s) => s.productId !== 'herramientas'); }
  function add() { if (!valid) return; if (editing) { const line = demo.state.cart.find((l) => l.id === editing); if (line) line.selections = JSON.parse(JSON.stringify(selections)); demo.drawer = true; demo.notice = demo.t('Kit actualizado', 'Kit updated'); } else demo.add({ kind: 'kit', projectId: project.id, selections, quantity: 1 }); }
</script>
<section id="kit" class="section"><h2>{demo.t('Kit del proyecto', 'Project kit')}</h2><p>{demo.t('Desmarca lo que ya tienes. Cambia la variante y el precio se recalcula.', 'Uncheck what you already have. Change the variant and the price recalculates.')}</p><div class="kit-layout"><div><div class="tabs"><button class:selected={!complete} onclick={() => mode(false)}>{demo.t('Kit básico', 'Basic kit')}</button><button class:selected={complete} onclick={() => mode(true)}>{demo.t('Kit completo + herramientas', 'Complete kit + tools')}</button></div>{#each selections as s,i}{@const p = productById(s.productId)}<div class="kit-item"><input type="checkbox" bind:checked={s.selected} aria-label={`${demo.t('Incluir', 'Include')} ${p.name}`}/><div><div class="eyebrow">{i+1} · {phaseNames[p.phase][demo.state.language]}</div><h3><a href={`/productos/${p.id}`}>{p.name}</a></h3><label>{demo.t('Cantidad', 'Quantity')}<input type="number" min="1" max="20" value={s.quantity} onchange={(e) => s.quantity = Math.max(1,Math.min(20,Number(e.currentTarget.value) || 1))}/></label></div><label>{demo.t('Formato / color / acabado', 'Format / color / finish')}<select bind:value={s.variantId}>{#each p.variants as v}<option value={v.id}>{v.format} · {v.color} {v.ral ? `RAL ${v.ral}` : ''} · {v.finish}{!v.stock ? ' · 0 stock' : ''}</option>{/each}</select></label><strong>{money(variantById(p.id,s.variantId).price*s.quantity,demo.state.language)}</strong></div>{/each}</div><aside class="kit-summary"><div class="eyebrow">{demo.t('TU SELECCIÓN · DEMO', 'YOUR SELECTION · DEMO')}</div><h3>{demo.t('Tu kit, a tu manera.', 'Your kit, your way.')}</h3><p>{selections.filter((s) => s.selected).length} / {selections.length} {demo.t('productos seleccionados', 'products selected')}</p><p>{demo.t('Por separado', 'Separately')}: {money(total.subtotal,demo.state.language)}</p><div class="price">{money(total.total,demo.state.language)}</div><p class="demo-note">{demo.t('Ahorro ficticio', 'Fictional saving')}: {money(total.discount,demo.state.language)} · {demo.t('10% solo al incluir las cuatro fases.', '10% only when all four phases are included.')}</p><button class="wide" disabled={!valid} onclick={add}>{editing ? demo.t('Actualizar kit en carrito', 'Update kit in cart') : demo.t('Añadir kit al carrito', 'Add kit to cart')}</button>{#if !valid}<p class="muted">{demo.t('Selecciona al menos un producto y variantes con stock demo.', 'Select at least one product and variants with demo stock.')}</p>{/if}<p class="muted" style="margin-top:16px">{demo.t('Precios, compatibilidades y cantidades de demostración.', 'Demo prices, compatibility and quantities.')}</p></aside></div></section>
